pub(crate) fn acquire_approved_model(
    &self,
    plan: &ManagedAcquisitionPlan,
    approval: &ManagedAcquisitionApproval,
    candidate_id: &str,
) -> Result<ManagedModelRegistration, ManagedLocalRuntimeError> {
    approval.authorizes(&plan.plan_id, candidate_id)?;
    let candidate = plan
        .candidates
        .iter()
        .find(|candidate| candidate.candidate_id == candidate_id)
        .ok_or_else(|| {
            ManagedLocalRuntimeError::new(
                ManagedDiagnosticLayer::ModelTransferOrIntegrity,
                "approved acquisition candidate is not present in the frozen plan",
            )
        })?;
    if !candidate.source.starts_with("https://") {
        return Err(ManagedLocalRuntimeError::new(
            ManagedDiagnosticLayer::ModelTransferOrIntegrity,
            "managed model acquisition requires an explicit HTTPS model URL",
        ));
    }
    if !is_sha256_hex(&candidate.expected_sha256) {
        return Err(ManagedLocalRuntimeError::new(
            ManagedDiagnosticLayer::ModelTransferOrIntegrity,
            "managed model acquisition requires an exact SHA-256 identity",
        ));
    }
    let downloads = self.root.join("downloads").join("models");
    fs::create_dir_all(&downloads).map_err(model_io)?;
    let path = downloads.join(format!(
        "{}.gguf",
        candidate.expected_sha256.to_ascii_lowercase()
    ));
    download_https_file(&candidate.source, &path)?;
    let metadata = fs::metadata(&path).map_err(model_io)?;
    if metadata.len() != candidate.transfer_bytes
        || candidate.storage_bytes < metadata.len()
    {
        let _ = fs::remove_file(&path);
        return Err(ManagedLocalRuntimeError::new(
            ManagedDiagnosticLayer::ModelTransferOrIntegrity,
            format!(
                "downloaded model size {} does not match frozen transfer/storage review {} / {}",
                metadata.len(), candidate.transfer_bytes, candidate.storage_bytes
            ),
        ));
    }
    verify_file_sha256(
        &path,
        &candidate.expected_sha256.to_ascii_lowercase(),
        ManagedDiagnosticLayer::ModelTransferOrIntegrity,
    )?;
    let mut registration = self.register_existing_gguf(&path, Some(&candidate.candidate_id))?;
    if registration.content_sha256 != candidate.expected_sha256.to_ascii_lowercase()
        || registration.size_bytes != candidate.transfer_bytes
    {
        return Err(ManagedLocalRuntimeError::new(
            ManagedDiagnosticLayer::ModelTransferOrIntegrity,
            "registered model identity changed after verified acquisition",
        ));
    }
    registration.quantization = Some(candidate.representation.clone());
    registration.source = Some(candidate.source.clone());
    registration.license = candidate.license.clone();
    let mut registry: ManagedModelRegistry = read_optional_json(&self.model_registry_path())
        .map_err(model_io)?
        .unwrap_or_default();
    if let Some(existing) = registry
        .models
        .iter_mut()
        .find(|model| model.content_sha256 == registration.content_sha256)
    {
        *existing = registration.clone();
    } else {
        registry.models.push(registration.clone());
        registry
            .models
            .sort_by(|left, right| left.model_id.cmp(&right.model_id));
    }
    write_json(&self.model_registry_path(), &registry).map_err(model_io)?;
    Ok(registration)
}

